function file = lm_export_step(D,g,outDir,name,mode)
% Write a codegen-able single-channel controller (persistent observer + energy swing-up + balance law)
% with all design constants as literals. Input x = [arm; pend; arm rate; pend rate] (only angles used).
% mode: "lmpc" (default), "lqr" or "pid" (balance law after capture).
if nargin<5, mode="lmpc"; end
mode=string(mode);
p=D.c.p;
S=@(v) mat2str(v,17);
L=[ "function [u,balancing] = "+name+"(x,active)"
"%#codegen"
"% Generated by lm_export_step: observer + energy swing-up + linear MPC (comparison-baseline plant)."
"persistent xh c1 c2 bal home"
"x=double(x(:)); u=0; balancing=false;"
"if isempty(xh) || ~active"
"    xh=[x(1);x(2);0;0]; c1=0; c2=0; bal=false; home=0;"
"    if ~active, u=0; balancing=false; return; end"
"else"
"    xp=lmRk4(xh,c2);"
"    e=[atan2(sin(x(1)-xp(1)),cos(x(1)-xp(1))); atan2(sin(x(2)-xp(2)),cos(x(2)-xp(2)))];"
"    xh=xp+"+S(D.L)+"*e;"
"end"
"xf=lmRk4(xh,c1);"
"th=atan2(sin(xf(2)),cos(xf(2))); w=xf(4); v=xf(3);"
"cap=abs(th)<"+S(g.capAng)+" && abs(w)<"+S(g.capRate)+";"
"if cap && ~bal, home=xf(1); end"
"bal=(bal && abs(th)<"+S(g.relAng)+") || cap;"
"if ~bal"
"    E=.5*"+S(p.beta2)+"*w^2+"+S(p.delta)+"*(cos(th)-1);"
"    d=sign(w*cos(th)); if d==0, d=1; end"
"    u="+S(g.kE)+"*E*d;"
"    if (E+2*"+S(p.delta)+")<"+S(g.Erest)+" && abs(th)>pi/2"
"        u=-sign(sin(th)); if u==0, u=-1; end"
"    end"
"    over=max(0,(abs(v)-"+S(g.v1)+")/("+S(g.v2-g.v1)+"));"
"    if sign(u)==sign(v), u=u*max(0,1-over); end"
"else"
"    z=[max(-"+S(g.armClamp)+",min("+S(g.armClamp)+",xf(1)-home)); th; v; w];"
"    H="+S(D.H)+";"
"    f="+S(D.Fq)+"*z;"
"    Gv="+S(D.Gv)+";"
"    fv="+S(D.Fv)+"*z;"
"    N="+D.N+";"
"    Ai=[eye(N);-eye(N);Gv;-Gv]; bi=[ones(2*N,1);"+S(D.vmax)+"-fv;"+S(D.vmax)+"+fv];"
"    opt=mpcActiveSetOptions;"
"    [U,st]=mpcActiveSetSolver(H,f,Ai,bi,zeros(0,N),zeros(0,1),false(4*N,1),opt);"
"    if st<=0"
"        [U,~]=mpcActiveSetSolver(H,f,[eye(N);-eye(N)],ones(2*N,1),zeros(0,N),zeros(0,1),false(2*N,1),opt);"
"    end"
"    u=U(1,1)+"+S(D.fc*p.coulomb/p.tau_max)+"*tanh(v/"+S(D.vs)+");"
"end"
"u=max(-1,min(1,u));"
"u=round(u*"+S(D.c.maxCurrent/D.c.currentLSB)+")/"+S(D.c.maxCurrent/D.c.currentLSB)+";"
"u=u(1); c2=c1; c1=u; balancing=logical(bal);"
"end"
""
"function x=lmRk4(x,a)"
"tau="+S(p.tau_max)+"*a; h="+S(p.h)+";"
"for i=1:"+round(D.c.Ts/p.h)
"    k1=f(x); k2=f(x+h/2*k1); k3=f(x+h/2*k2); k4=f(x+h*k3);"
"    x=x+h/6*(k1+2*k2+2*k3+k4);"
"end"
"    function y=f(z)"
"        s=sin(z(2)); c=cos(z(2)); vv=z(3); ww=z(4);"
"        dd="+S(p.alpha)+"+"+S(p.beta)+"*s^2; b="+S(p.gam)+"*c;"
"        ff=tau-2*"+S(p.beta)+"*s*c*vv*ww+"+S(p.gam)+"*s*ww^2-"+S(p.eta_phi)+"*vv-"+S(p.coulomb)+"*sign(vv);"
"        gg="+S(p.beta)+"*s*c*vv^2-"+S(p.eta_theta)+"*ww+"+S(p.delta)+"*s;"
"        dt=dd*"+S(p.beta2)+"-b^2;"
"        y=[z(3);z(4);("+S(p.beta2)+"*ff-b*gg)/dt;(dd*gg-b*ff)/dt];"
"    end"
"end"];
if mode~="lmpc"
    i0=find(startsWith(L,"    H="),1); i1=find(startsWith(L,"    u=U(1,1)+"),1);
    ff="+"+S(D.fc*p.coulomb/p.tau_max)+"*tanh(v/"+S(D.vs)+")";
    guard="    if abs(v)>"+S(g.vGuard)+" && sign(ub)==sign(v), ub=0; end";
    if mode=="lqr"
        blk=["    ub="+S(-D.K)+"*z;"; guard; "    u=ub"+ff+";"];
    else
        G=g.pid;
        blk=["    cand="+S(G(1))+"*z(2)+"+S(G(2))+"*z(4)+"+S(G(3))+"*z(1)+"+S(G(4))+"*z(3)+"+S(G(5))+"*(iint+"+S(D.c.Ts)+"*z(2));"
             "    if abs(cand)<=1 || sign(cand)~=sign(z(2)), iint=iint+"+S(D.c.Ts)+"*z(2); end"
             "    ub="+S(G(1))+"*z(2)+"+S(G(2))+"*z(4)+"+S(G(3))+"*z(1)+"+S(G(4))+"*z(3)+"+S(G(5))+"*iint;"
             guard; "    u=ub"+ff+";"];
    end
    L=[L(1:i0-1); blk; L(i1+1:end)];
    L=strrep(L,"persistent xh c1 c2 bal home","persistent xh c1 c2 bal home iint");
    L=strrep(L,"    xh=[x(1);x(2);0;0]; c1=0; c2=0; bal=false; home=0;","    xh=[x(1);x(2);0;0]; c1=0; c2=0; bal=false; home=0; iint=0;");
    L=strrep(L,"if ~bal","if ~bal" + newline + "    iint=0;");
    L=strrep(L,"Generated by lm_export_step: observer + energy swing-up + linear MPC","Generated by lm_export_step: observer + energy swing-up + "+upper(mode));
end
if isfield(g,'noSwing') && g.noSwing
    % balance-only variant for first hardware tests: zero command until captured near upright
    i0=find(startsWith(L,"if ~bal"),1); i1=find(strcmp(L,"else"));
    i1=i1(find(i1>i0,1));
    L=[L(1:i0); "    u=0;"; L(i1:end)];
    L=strrep(L,"observer + energy swing-up +","observer + (NO swing-up, balance only) +");
end
if (isfield(g,'brakeMax') && isfinite(g.brakeMax)) || (isfield(g,'slew') && isfinite(g.slew)) || (isfield(g,'brakeMaxBal') && isfinite(g.brakeMaxBal)) || (isfield(g,'slewBal') && isfinite(g.slewBal))
    % regeneration guard / slew limit, inserted after the +-1 clip (same as lm_controller)
    i0=find(strcmp(L,"u=max(-1,min(1,u));"),1); add=strings(0,1);
    if isfield(g,'brakeMax') && isfinite(g.brakeMax)
        add(end+1)="if ~bal && u~=0 && sign(u)~=sign(v) && abs(v)>"+S(g.brakeV)+", u=sign(u)*min(abs(u),"+S(g.brakeMax)+"); end";
    end
    if isfield(g,'brakeMaxBal') && isfinite(g.brakeMaxBal)
        add(end+1)="if bal && u~=0 && sign(u)~=sign(v) && abs(v)>"+S(g.brakeVBal)+", u=sign(u)*min(abs(u),"+S(g.brakeMaxBal)+"); end";
    end
    if isfield(g,'slew') && isfinite(g.slew)
        add(end+1)="u=c1+max(-"+S(g.slew)+",min("+S(g.slew)+",u-c1));";
    end
    if isfield(g,'slewBal') && isfinite(g.slewBal)   % balance-only command slew limit (2026-11-22, against LMPC chatter)
        add(end+1)="if bal, u=c1+max(-"+S(g.slewBal)+",min("+S(g.slewBal)+",u-c1)); end";
    end
    L=[L(1:i0); add(:); L(i0+1:end)];
end
if isfield(g,'fcOnCmd') && g.fcOnCmd
    % Coulomb feed-forward keyed on the commanded direction instead of the estimated arm rate
    L=strrep(L,"u=ub+"+S(D.fc*p.coulomb/p.tau_max)+"*tanh(v/","u=ub+"+S(D.fc*p.coulomb/p.tau_max)+"*tanh(ub/");
end
if isfield(g,'pidScale') && g.pidScale~=1
    G=g.pid; Gs=G; Gs(1:4)=G(1:4)*g.pidScale;
    for q=1:4, L=strrep(L,S(G(q))+"*z(",S(Gs(q))+"*z("); end
end
if isfield(g,'thOffsetDeg') && g.thOffsetDeg~=0
    % pendulum zero trim inside the controller: true angle = measured - offset (sensor JSON untouched)
    L=strrep(L,"x=double(x(:)); u=0; balancing=false;", ...
        "x=double(x(:)); x(2)=x(2)-"+S(deg2rad(g.thOffsetDeg))+"; u=0; balancing=false;");
end
file=fullfile(outDir,name+".m"); writelines(L,file);
end
